#include "piper_workbench/main_window.hpp"
#include "piper_workbench/backend_client.hpp"
#include "piper_workbench/motion_controller.hpp"
using namespace Ui;
QWidget *MainWindow::makeConnections(){
 auto *page=new QWidget;page->setObjectName("page");auto *layout=new QVBoxLayout(page);layout->setContentsMargins(20,20,20,16);layout->setSpacing(14);auto *head=new QHBoxLayout;auto *titles=new QVBoxLayout;titles->addWidget(text("连接与启动","pageTitle"));titles->addWidget(text("按需启动组件，已运行的直接复用"));head->addLayout(titles,1);
 for(auto pair:QList<QPair<QString,QString>>{{"碰撞后恢复","arm.recover"},{"一键启动全部","system.start_missing"},{"关闭所有连接","system.stop_all"},{"刷新状态","status.get"},{"取消剩余启动","system.cancel"}}){auto *b=button(pair.first,pair.second=="system.start_missing",pair.second=="arm.recover"?"refresh":"play");b->setMinimumWidth(0);if(pair.second=="system.stop_all"){b->setObjectName("danger");b->setToolTip("暂停并取消任务，关闭组件、断开传送带并关闭 CAN；工作台窗口保留");}head->addWidget(b);connect(b,&QPushButton::clicked,this,[this,pair]{if(pair.second=="status.get"){refresh();return;}if(pair.second=="system.stop_all")motion_->stop();backend_->call(pair.second,{},[this,pair](QJsonValue v){connectionLog_->appendPlainText(QJsonDocument(v.isObject()?QJsonDocument(v.toObject()):QJsonDocument(v.toArray())).toJson(QJsonDocument::Indented));if(pair.second=="system.stop_all"){int failed=0;for(auto row:v.toArray())if(row.toObject().contains("error"))++failed;connectionState_->setText(failed?QString("关闭流程已执行 · %1 项未完成，详情见下方日志").arg(failed):"所有连接已关闭 · 工作台保留");toast_->setText(connectionState_->text());}if(pair.second=="arm.recover")connectionState_->setText("连接流程已完成，使能待实际反馈确认 · 抓取保持暂停");refresh();});});}layout->addLayout(head);
 auto *cards=new QWidget;auto *grid=new QGridLayout(cards);grid->setContentsMargins(0,0,0,0);grid->setSpacing(12);
 struct Item{QString title,component,camera,detail;};QList<Item> items={{"CAN 连接","can","d455","can0 · 1000000 bit/s\n原激活脚本 + cansend"},{"机械臂激活","activate","d455","Piper · 原 activate_robot.py\n状态以实际使能反馈为准"},{"机械臂与规划","arm","d455","T1 · MoveIt\n使用当前活动 TCP / 模型"},{"D455 相机","camera","d455","640 × 480 · 30 帧/秒"},{"Dabai 相机","camera","dabai","640 × 480 · 15 帧/秒"},{"双路 YOLO","detector","dual","一份模型 · 两路结果\nfruits12.pt"},{"分拣动作","action","d455","T5 · auto_sorting_action.py\n原程序启动时会回待机并开夹爪"},{"D455 坐标变换","camera_tf","d455","base_link → optical\n活动手眼外参"},{"Dabai 坐标变换","camera_tf","dabai","按 manifest 末端语义\n活动手眼外参"},{"传送带通信","conveyor","d455","USB 串口 · 115200\n独立连接，不自动启带"}};
 for(int col=0;col<12;++col)grid->setColumnStretch(col,1);
 for(int i=0;i<items.size();++i){auto item=items[i];auto *box=card(item.title);box->setMinimumHeight(175);box->setSizePolicy(QSizePolicy::Expanding,QSizePolicy::Preferred);auto *bl=static_cast<QVBoxLayout *>(box->layout());bl->setSpacing(8);bl->addWidget(text(item.detail));auto *state=text("未启动 / 状态待刷新","notice");componentStates_[item.component+":"+item.camera]=state;bl->addWidget(state);auto *bar=new QHBoxLayout;
  for(QString action:{"启动","停止","日志"}){if(action=="停止"&&(item.component=="can"||item.component=="activate"))continue;auto *b=button(action,action=="启动"&&(item.component=="can"||item.component=="activate"),action=="日志"?"logs":action=="停止"?"stop":"play");bar->addWidget(b);connect(b,&QPushButton::clicked,this,[this,item,action]{if(action=="日志"){showPage(5);logSource_->setCurrentText(item.component);filterLogs();return;}backend_->call(action=="启动"?"component.start":"component.stop",{{"component",item.component},{"camera_id",item.camera}},[this](QJsonValue v){connectionLog_->appendPlainText(QJsonDocument(v.toObject()).toJson(QJsonDocument::Indented));refresh();});});}bl->addLayout(bar);if(i<3)grid->addWidget(box,0,i*4,1,4);else grid->addWidget(box,1+(i-3)/4,((i-3)%4)*3,1,3);
 }layout->addWidget(cards,2);
 auto *recovery=card("碰撞保护恢复");auto *rl=static_cast<QVBoxLayout *>(recovery->layout());rl->addWidget(text("请先移开碰撞障碍。流程包含重新使能，完成后保持暂停，由你再次开始抓取。","notice"));connectionState_=text("① 暂停任务、停带并取消旧目标  →  ② 停止旧 T1  →  ③ CAN 激活  →  ④ 机械臂激活  →  ⑤ 重启 T1  →  ⑥ 保持暂停");rl->addWidget(connectionState_);Ui::collapsible(recovery);layout->addWidget(recovery);
 auto *output=card("执行命令与完整输出");auto *ol=static_cast<QVBoxLayout *>(output->layout());connectionLog_=new QPlainTextEdit;connectionLog_->setReadOnly(true);connectionLog_->setMaximumBlockCount(10000);connectionLog_->setMinimumHeight(100);ol->addWidget(connectionLog_,1);Ui::collapsible(output);layout->addWidget(output,1);page->setMinimumHeight(880);return Ui::scroll(page);
}
